<?php
declare(strict_types=1);require '../config/db.php';require '../config/auth.php';require_role('parishioner','login.php');$u=current_user();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$s=$pdo->prepare("UPDATE appointments SET status='cancelled' WHERE id=? AND user_id=? AND status='pending'");$s->execute([$id,$u['id']]);if($s->rowCount()){$pdo->prepare("INSERT INTO appointment_history(appointment_id,status,note,changed_by) VALUES(?,'cancelled','Cancelled by parishioner',?)")->execute([$id,$u['id']]);flash('success','Appointment cancelled.');}redirect('my-appointments.php');}$s=$pdo->prepare("SELECT a.*,s.name service_name,r.name resource_name FROM appointments a JOIN services s ON s.id=a.service_id LEFT JOIN resources r ON r.id=a.resource_id WHERE a.user_id=? ORDER BY a.appointment_date DESC,a.start_time DESC");$s->execute([$u['id']]);$rows=$s->fetchAll();$pageTitle='My appointments.';$eyebrow='Bookings';?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Appointments</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="shell"><?php include 'includes/sidebar.php'?><main class="main"><?php include 'includes/header.php'?><section class="card table-wrap appointments-page-card" data-live-scope><div class="actions" style="justify-content:flex-end;margin-bottom:12px"><a class="btn" href="book-service.php">Book another service</a></div><div class="live-filter-bar"><label class="field live-search-field">Search<input class="search" type="search" data-live-search placeholder="Search reference, service, date, resource..."></label><label class="field">Status<select data-live-filter="status"><option value="">All statuses</option><?php foreach(['pending','approved','rejected','completed','cancelled'] as $x):?><option value="<?=$x?>"><?=ucfirst($x)?></option><?php endforeach?></select></label><label class="field">Service<select data-live-filter="service"><option value="">All services</option><?php foreach(array_values(array_unique(array_column($rows,'service_name'))) as $x):?><option value="<?=e(strtolower($x))?>"><?=e($x)?></option><?php endforeach?></select></label><button type="button" class="btn light" data-live-clear>Clear</button><span class="live-filter-meta" data-live-count></span></div><table class="table appointments-table"><thead><tr><th>Reference</th><th>Service</th><th>Schedule</th><th>Resource</th><th>Status</th><th>Action</th></tr></thead><tbody data-live-list><tr data-live-empty class="live-empty" hidden><td colspan="6">No appointments match your search or filters.</td></tr><?php if(!$rows):?><tr><td colspan="6" class="muted">No appointments yet.</td></tr><?php endif?><?php foreach($rows as $a):?><tr data-live-item data-status="<?=e(strtolower($a['status']))?>" data-service="<?=e(strtolower($a['service_name']))?>" data-search="<?=e(strtolower($a['reference_no'].' '.$a['service_name'].' '.$a['appointment_date'].' '.($a['resource_name']??'').' '.$a['status']))?>"><td class="appt-reference" data-label="Reference"><b><?=e($a['reference_no'])?></b></td><td class="appt-service" data-label="Service"><?=e($a['service_name'])?></td><td class="appt-schedule" data-label="Schedule"><?=date('M j, Y',strtotime($a['appointment_date']))?><br><?=date('g:i A',strtotime($a['start_time']))?>–<?=date('g:i A',strtotime($a['end_time']))?></td><td class="appt-resource" data-label="Resource"><?=e($a['resource_name']??'—')?></td><td class="appt-status" data-label="Status"><span class="badge <?=e($a['status'])?>"><?=e($a['status'])?></span></td><td class="appt-action" data-label="Action"><div class="actions"><a class="btn light small" href="appointment-details.php?id=<?=$a['id']?>">View details</a><?php if($a['status']==='pending'):?><form method="post" onsubmit="return confirm('Cancel this appointment?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$a['id']?>"><button class="btn danger small">Cancel</button></form><?php endif?></div></td></tr><?php endforeach?></tbody></table></section></main></div><script src="../assets/js/script.js"></script></body></html>
